class Solution:
    def cycleLengthQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        res = []
        for a, b in queries:
            da, db = a.bit_length() - 1, b.bit_length() - 1
            ra, rb = a, b
            while da > db:
                ra //= 2; da -= 1
            while db > da:
                rb //= 2; db -= 1
            while ra != rb:
                ra //= 2; rb //= 2
            res.append(a.bit_length() + b.bit_length() - 2 * ra.bit_length() + 1)
        return res

