class Solution {
    public int[] cycleLengthQueries(int n, int[][] queries) {
        int[] res = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            long a = queries[i][0], b = queries[i][1];
            int da = dep(a), db = dep(b);
            long ra = a, rb = b;
            while (da > db) { ra >>= 1; da--; }
            while (db > da) { rb >>= 1; db--; }
            while (ra != rb) { ra >>= 1; rb >>= 1; }
            res[i] = dep(a) + dep(b) - 2 * dep(ra) + 1;
        }
        return res;
    }
    private int dep(long v) { int d = 0; while (v > 1) { v >>= 1; d++; } return d; }
}

