var cycleLengthQueries = function(n, queries) {
    const dep = v => { let d = 0; while (v > 1) { v = Math.floor(v / 2); d++; } return d; };
    return queries.map(([a, b]) => {
        let ra = a, rb = b, da = dep(a), db = dep(b);
        while (da > db) { ra = Math.floor(ra / 2); da--; }
        while (db > da) { rb = Math.floor(rb / 2); db--; }
        while (ra !== rb) { ra = Math.floor(ra / 2); rb = Math.floor(rb / 2); }
        return dep(a) + dep(b) - 2 * dep(ra) + 1;
    });
};

